SELECT count() AS mismatches FROM (SELECT owner_key,field_name,value,author_key,doc_id,version,sum(weight) AS delta FROM (SELECT owner_key,field_name,value,author_key,doc_id,version,toInt8(1) AS weight FROM (SELECT * FROM strings WHERE field_name='body:repost_of') UNION ALL SELECT owner_key,field_name,value,author_key,doc_id,version,toInt8(-1) AS weight FROM (SELECT JSONExtractString(body,'repost_of') AS owner_key,'body:repost_of' AS field_name,doc_id AS value,author_key,doc_id,updated_at AS version FROM documents FINAL WHERE deleted=0 AND collection_name='posts' AND owner_key!='')) GROUP BY owner_key,field_name,value,author_key,doc_id,version HAVING delta!=0)
